"""Convert frozen source OBJ assets to explicit glTF coordinates with round-trip checks."""
import argparse,json,hashlib,gc
from pathlib import Path
import numpy as np,trimesh
from revision_expansion_common import OUT,write,sha
ROOT=OUT/'iteration012_condition_interference/gso_sources'
def texturehash(mesh):return hashlib.sha256(np.asarray(mesh.visual.material.image.convert('RGB')).tobytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--count',type=int,default=100);a=ap.parse_args();records=json.loads((ROOT/'DOWNLOAD_ROWS.json').read_text());records=sorted([x for x in records if x['status']=='DOWNLOADED_AND_EXTRACTED_SOURCE_ASSET'],key=lambda x:x['name'])[:a.count];assert len(records)==a.count;dest=ROOT/f'canonical_glb_attempt01_n{a.count}';assert not dest.exists();dest.mkdir();rotation=np.array([[1.,0.,0.],[0.,0.,1.],[0.,-1.,0.]]);assert np.array_equal(rotation@np.array([0.,0.,1.]),[0.,1.,0.]);assert np.isclose(np.linalg.det(rotation),1.);write(dest/'INPUT_CONVERSION_FREEZE.json',{'names':[x['name'] for x in records],'rotation_obj_to_gltf':rotation.tolist(),'normalization':'none; source dimensions preserved, native render normalization separate','selection':'fixed input name order, no method outputs','source_sha256':sha(Path(__file__))});(dest/'execution_source.py').write_bytes(Path(__file__).read_bytes());results=[]
 for row in records:
  source=Path(row['model_path']);output=dest/(row['name']+'.glb');result={'name':row['name'],'source_model_sha256':sha(source)}
  try:
   assert result['source_model_sha256']==row['model_sha256'];resolver={Path(x).name:Path(x).read_bytes() for x in row['material_files']+row['texture_files']};scene=trimesh.load(str(source),force='scene',process=False,resolver=trimesh.resolvers.ZipResolver(resolver));assert len(scene.geometry)==1,'Multi-geometry source requires explicit material mapping';mesh=next(iter(scene.geometry.values()));expected_vertices=mesh.vertices@rotation.T;expected_uv=np.asarray(mesh.visual.uv).copy();expected_faces=mesh.faces.copy();image_hash=texturehash(mesh);transform=np.eye(4);transform[:3,:3]=rotation;mesh.apply_transform(transform);output.write_bytes(trimesh.Scene(mesh).export(file_type='glb'));restored=trimesh.load(str(output),force='scene',process=False);assert len(restored.geometry)==1;loaded=next(iter(restored.geometry.values()));assert np.array_equal(loaded.faces,expected_faces);assert loaded.vertices.shape==expected_vertices.shape and np.allclose(loaded.vertices,expected_vertices,atol=1e-6,rtol=1e-6);assert np.allclose(np.asarray(loaded.visual.uv),expected_uv,atol=1e-7);material=loaded.visual.material;texture=getattr(material,'baseColorTexture',None);assert texture is not None;actual_hash=hashlib.sha256(np.asarray(texture.convert('RGB')).tobytes()).hexdigest();assert actual_hash==image_hash;assert sha(source)==row['model_sha256'];result.update(status='PASS_RIGID_SOURCE_TO_GLTF_ROUNDTRIP',glb_path=str(output.resolve()),glb_sha256=sha(output),vertices=len(loaded.vertices),triangles=len(loaded.faces),uv_roundtrip_pass=True,texture_pixel_sha256=image_hash,source_dimension_preserved=True,vertex_max_error=float(np.abs(loaded.vertices-expected_vertices).max()),scope='glTF conversion with unchanged topology, UV and texture pixels; material encoding converted by Trimesh, not exact original OBJ shader semantics. Source appearance not certified physical albedo.');del scene,mesh,loaded,restored,resolver;gc.collect()
  except Exception as exc:result.update(status='FAILED_CANONICAL_SOURCE_CONVERSION',error=f'{type(exc).__name__}: {exc}')
  results.append(result);write(dest/'CANONICAL_GLTF_ROWS.json',results);print(len(results),result['status'],row['name'],flush=True)
 write(dest/'CANONICAL_GLTF_STATUS.json',{'status':'COMPLETE_ALL_CANONICAL_CONVERSION_ATTEMPTS','requested':a.count,'pass_count':sum(x['status'].startswith('PASS_') for x in results),'failed_count':sum(x['status'].startswith('FAILED_') for x in results),'scope':'Input conversion only; actual native renderer camera and material appearance calibration still pending. Failure records retained.'})
if __name__=='__main__':main()
